<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Form & Function — Digital Design Studio</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@300;400;500;600;700&family=Syne:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #0a0a0b;
      --bg-elevated: #131316;
      --fg: #fafafa;
      --muted: #71717a;
      --accent: #e4e4e7;
      --accent-dim: #3f3f46;
      --card: #18181b;
      --border: #27272a;
      --gold: #d4a843;
      --gold-dim: #8b7333;
    }

    * { box-sizing: border-box; }

    @media (prefers-color-scheme: light) {
      :root {
        --bg: #fafafa;
        --bg-elevated: #ffffff;
        --fg: #0a0a0b;
        --muted: #71717a;
        --accent: #18181b;
        --accent-dim: #e4e4e7;
        --card: #ffffff;
        --border: #e4e4e7;
        --gold: #b8860b;
        --gold-dim: #8b6914;
      }
    }

    html { scroll-behavior: auto; }

    body {
      font-family: 'Space Grotesk', sans-serif;
      background: var(--bg);
      color: var(--fg);
      overflow-x: hidden;
      line-height: 1.6;
    }

    .font-display { font-family: 'Syne', sans-serif; }

    /* Custom scrollbar */
    ::-webkit-scrollbar { width: 8px; }
    ::-webkit-scrollbar-track { background: var(--bg); }
    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
    ::-webkit-scrollbar-thumb:hover { background: var(--muted); }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    /* Reveal animations */
    .reveal {
      opacity: 0;
      transform: translateY(40px);
      transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), 
                  transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    .reveal-delay-1 { transition-delay: 0.1s; }
    .reveal-delay-2 { transition-delay: 0.2s; }
    .reveal-delay-3 { transition-delay: 0.3s; }
    .reveal-delay-4 { transition-delay: 0.4s; }
    .reveal-delay-5 { transition-delay: 0.5s; }

    .reveal-scale {
      opacity: 0;
      transform: scale(0.95) translateY(20px);
      transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), 
                  transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .reveal-scale.visible { opacity: 1; transform: scale(1) translateY(0); }

    .reveal-rotate {
      opacity: 0;
      transform: rotate(-3deg) translateY(30px) scale(0.98);
      transition: opacity 0.9s cubic-bezier(0.16, 1, 0.3, 1), 
                  transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .reveal-rotate.visible { opacity: 1; transform: rotate(0) translateY(0) scale(1); }

    /* Text reveal */
    .text-reveal {
      overflow: hidden;
      display: inline-block;
    }
    .text-reveal span {
      display: block;
      transform: translateY(110%);
      transition: transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .text-reveal.visible span { transform: translateY(0); }

    /* Stagger children */
    .stagger-children > * { opacity: 0; transform: translateY(30px); transition: opacity 0.6s cubic-bezier(0.16, 1, 0.3, 1), transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); }
    .stagger-children.visible > * { opacity: 1; transform: translateY(0); }
    .stagger-children > *:nth-child(1) { transition-delay: 0.05s; }
    .stagger-children > *:nth-child(2) { transition-delay: 0.1s; }
    .stagger-children > *:nth-child(3) { transition-delay: 0.15s; }
    .stagger-children > *:nth-child(4) { transition-delay: 0.2s; }
    .stagger-children > *:nth-child(5) { transition-delay: 0.25s; }
    .stagger-children > *:nth-child(6) { transition-delay: 0.3s; }

    /* Parallax layers */
    .parallax-wrapper { position: relative; overflow: hidden; }
    .parallax-layer { position: absolute; top: 0; left: 0; width: 100%; height: 100%; will-change: transform; }

    /* Magnetic button */
    .magnetic-btn {
      position: relative;
      overflow: hidden;
      transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .magnetic-btn::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, var(--gold) 0%, #f5d06e 100%);
      opacity: 0;
      transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1);
      z-index: -1;
    }
    .magnetic-btn:hover::before { opacity: 1; }
    .magnetic-btn:hover { color: var(--bg); box-shadow: 0 20px 40px -20px var(--gold); }

    /* Card hover */
    .project-card {
      transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), 
                  box-shadow 0.5s cubic-bezier(0.16, 1, 0.3, 1),
                  border-color 0.3s ease;
    }
    .project-card:hover {
      transform: translateY(-8px) scale(1.01);
      box-shadow: 0 30px 60px -20px rgba(0,0,0,0.4);
      border-color: var(--gold);
    }
    .project-card .card-image {
      transition: transform 0.8s cubic-bezier(0.16, 1, 0.3, 1), filter 0.5s ease;
    }
    .project-card:hover .card-image {
      transform: scale(1.05);
      filter: brightness(0.7);
    }
    .project-card .card-overlay {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1), transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .project-card:hover .card-overlay {
      opacity: 1;
      transform: translateY(0);
    }

    /* Nav */
    .nav-link {
      position: relative;
      color: var(--muted);
      transition: color 0.3s ease;
    }
    .nav-link::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--gold);
      transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .nav-link:hover, .nav-link.active { color: var(--fg); }
    .nav-link:hover::after, .nav-link.active::after { width: 100%; }

    /* Stats counter */
    .stat-value { 
      font-variant-numeric: tabular-nums; 
      font-feature-settings: "tnum";
    }

    /* Marquee */
    .marquee { display: flex; animation: marquee 20s linear infinite; will-change: transform; }
    .marquee:hover { animation-play-state: paused; }
    @keyframes marquee {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    .marquee-reverse { animation-direction: reverse; }

    /* Cursor follower */
    .cursor-glow {
      position: fixed;
      width: 400px;
      height: 400px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(212, 168, 67, 0.08) 0%, transparent 70%);
      pointer-events: none;
      z-index: 9998;
      transform: translate(-50%, -50%);
      transition: opacity 0.3s ease, width 0.3s ease, height 0.3s ease;
      opacity: 0;
    }
    .cursor-glow.active { opacity: 1; }

    /* Focus visible */
    :focus-visible {
      outline: 2px solid var(--gold);
      outline-offset: 3px;
    }

    /* Selection */
    ::selection { background: var(--gold); color: var(--bg); }

    /* Noise texture overlay */
    .noise-overlay::before {
      content: '';
      position: fixed;
      inset: 0;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
      opacity: 0.03;
      pointer-events: none;
      z-index: 9999;
    }

    /* Gradient text */
    .gradient-text {
      background: linear-gradient(135deg, var(--fg) 0%, var(--gold) 50%, var(--fg) 100%);
